import sys

def is_palindrome(s):
    return s == s[::-1]

def main():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        A = input[index]
        B = input[index + 1]
        index += 2
        found = False
        len_a = len(A)
        len_b = len(B)
        for i in range(len_a):
            for j in range(i + 1, len_a + 1):
                s1 = A[i:j]
                for k in range(len_b):
                    for l in range(k + 1, len_b + 1):
                        s2 = B[k:l]
                        if is_palindrome(s1 + s2):
                            found = True
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                break
        results.append("Yes" if found else "No")
    print("\n".join(results))

if __name__ == "__main__":
    main()
